from typing import Callable

def head_sum(a: float, m: int) -> float:
    """H_a(m) = sum_{k=1}^{m} k^(-a)."""
    return sum(float(k) ** (-a) for k in range(1, m + 1))

def head_mass(a: float, n: int, m: int) -> float:
    """M_a(n, m) = H_a(m) / H_a(n): the fraction of weight in the head window."""
    return head_sum(a, m) / head_sum(a, n)

def implied_exponent(target: float, n: int, m: int,
                     lo: float = -5.0, hi: float = 20.0,
                     tol: float = 1e-12, max_iter: int = 200) -> float:
    """Unique c with M_c(n, m) = target.

    The map c |-> M_c(n, m) is continuous and strictly increasing (monotone likelihood
    ratio implies first-order stochastic dominance), so the root exists and is unique and
    bisection converges monotonically.
    """
    if not (head_mass(lo, n, m) <= target <= head_mass(hi, n, m)):
        raise ValueError("target outside bracketing interval")
    for _ in range(max_iter):
        mid = 0.5 * (lo + hi)
        if head_mass(mid, n, m) < target:
            lo = mid
        else:
            hi = mid
        if hi - lo < tol:
            break
    return 0.5 * (lo + hi)

def head_sum(a: float, m: int) -> float:
    return sum(float(k) ** (-a) for k in range(1, m + 1))

def mix_head_mass(w: float, a: float, b: float, n: int, m: int) -> float:
    """Head mass of (1-w) k^-a + w k^-b, using additivity of the head sums."""
    num = (1.0 - w) * head_sum(a, m) + w * head_sum(b, m)
    den = (1.0 - w) * head_sum(a, n) + w * head_sum(b, n)
    return num / den

def recover_weight(target: float, a: float, b: float, n: int, m: int,
                   tol: float = 1e-14, max_iter: int = 200) -> float:
    """Unique w in [0,1] with mix_head_mass(w, a, b, n, m) = target.

    Strict monotonicity in w follows from positivity of the determinant
    H_b(m) H_a(n) - H_a(m) H_b(n), so bisection converges to the unique solution.
    """
    lo, hi = 0.0, 1.0
    for _ in range(max_iter):
        mid = 0.5 * (lo + hi)
        if mix_head_mass(mid, a, b, n, m) < target:
            lo = mid
        else:
            hi = mid
        if hi - lo < tol:
            break
    return 0.5 * (lo + hi)

import math

def head_sum(a: float, m: int) -> float:
    return sum(float(k) ** (-a) for k in range(1, m + 1))

def calibrate_dial(value: float, a: float, n: int) -> float:
    """Rescale a head dial recorded at truncation n to a truncation-free quantity.

    Regimes:
      a  < 1 : the dial decays like n^(a-1); multiply by n^(1-a), limit (1-a) H_a(m).
      a == 1 : the dial decays like 1/log n; multiply by log n, limit H(m).
      a  > 1 : the dial saturates; no rescaling is required.
    """
    if a < 1.0:
        return value * float(n) ** (1.0 - a)
    if a == 1.0:
        return value * math.log(n)
    return value

def predicted_doubling_ratio(a: float) -> float:
    """Asymptotic factor by which the dial changes when the truncation is doubled."""
    if a < 1.0:
        return 2.0 ** (a - 1.0)
    return 1.0  # neutral at a = 1 (and trivially 1 for a > 1, where the dial saturates)

def regime_from_squaring_ratio(ratio: float, tol: float = 0.05) -> str:
    """Diagnose the regime from the observed effect of squaring the truncation."""
    if abs(ratio - 0.5) <= tol:
        return "harmonic threshold (a = 1): limit is zero despite the flat appearance"
    if ratio < 0.5 - tol:
        return "sub-harmonic (a < 1): polynomial collapse"
    return "super-harmonic (a > 1): genuine saturation"
